int videobuf_vmalloc_mapper(struct videobuf_queue *q, struct vm_area_struct *vma)
{
    struct videobuf_buffer *buf = NULL;
    struct videobuf_mapping *mapping;
    int ret = -EINVAL;

    if (vma->vm_flags & (VM_WRITE | VM_SHARED)) {
        list_for_each_entry(buf, &q->queued_list, q) {
            if (vma->vm_start >= buf->bo->offset &&
                vma->vm_end <= buf->bo->offset + buf->bo->size) {
                mapping = kmalloc(sizeof(*mapping), GFP_KERNEL);
                if (!mapping)
                    return -ENOMEM;

                mapping->vma = vma;
                mapping->buf = buf;
                vma->vm_private_data = mapping;

                vma->vm_ops = &videobuf_vm_ops;
                ret = remap_pfn_range(vma, vma->vm_start,
                                      PFN_DOWN(buf->bo->dma_addr),
                                      vma->vm_end - vma->vm_start,
                                      vma->vm_page_prot);

                if (!ret)
                    videobuf_vm_open(vma);

                return ret;
            }
        }

        mapping = kmalloc(sizeof(*mapping), GFP_KERNEL);
        if (!mapping)
            return -ENOMEM;

        mapping->vma = vma;
        mapping->buf = NULL;
        vma->vm_private_data = mapping;
        vma->vm_ops = &videobuf_vm_ops;

        return 0;
    }

    return -EINVAL;
}

int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
    struct videobuf_buffer *buf;

    if (vma->vm_flags & (VM_WRITE | VM_SHARED)) {
        list_for_each_entry(buf, &q->queued_list, q) {
            if (vma->vm_start == buf->baddr) {
                struct videobuf_mapping *map;
                map = kmalloc(sizeof(*map), GFP_KERNEL);
                if (!map)
                    return -ENOMEM;

                map->vma = vma;
                map->buf = buf;
                list_add(&map->list, &buf->mappings);

                vma->vm_ops = &videobuf_vm_ops;
                vma->vm_private_data = buf;

                if (remap_pfn_range(vma, vma->vm_start, buf->dma_addr >> PAGE_SHIFT,
                                    vma->vm_end - vma->vm_start, vma->vm_page_prot)) {
                    kfree(map);
                    return -ENOMEM;
                }

                do_open_vma(vma);
                return 0;
            }
        }
    }

    return -EINVAL;
}

int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
    struct videobuf_buffer *buf;

    if (!(vma->vm_flags & VM_SHARED) || !(vma->vm_flags & VM_WRITE))
        return -EINVAL;

    list_for_each_entry(buf, &q->queued_list, q) {
        if (vma->vm_start == q->offsets[buf->i] &&
            vma->vm_end == q->offsets[buf->i] + PAGE_SIZE) {
            buf->vma = vma;
            vma->vm_ops = &videobuf_vm_ops;
            vma->vm_private_data = buf;
            if (remap_pfn_range(vma, vma->vm_start,
                                page_to_pfn(buf->vb2_buf->planes[0].dma_addr),
                                vma->vm_end - vma->vm_start,
                                vma->vm_page_prot)) {
                return -ENOMEM;
            }
            return 0;
        }
    }

    return -EINVAL;
}

int videobuf_mmap(struct videobuf_queue *q, struct vm_area_struct *vma)
{
    struct videobuf_buffer *b;
    int ret = -EINVAL;

    if (vma->vm_flags & (VM_WRITE | VM_SHARED)) {
        list_for_each_entry(b, &q->queued_list, q) {
            if (vma->vm_start >= b->bo->offset &&
                vma->vm_end <= b->bo->offset + b->bo->size) {
                struct videobuf_mapping *map;
                map = kzalloc(sizeof(*map), GFP_KERNEL);
                if (!map)
                    return -ENOMEM;

                map->vma = vma;
                map->buf = b;
                vma->vm_private_data = map;

                vma->vm_ops = &videobuf_vm_ops;
                vma->vm_flags |= VM_IO | VM_DONTCOPY | VM_PFNMAP;

                ret = remap_pfn_range(vma, vma->vm_start,
                                      PFN_DOWN(b->bo->dma_addr),
                                      b->bo->size, vma->vm_page_prot);
                if (ret) {
                    vma->vm_private_data = NULL;
                    kfree(map);
                    return ret;
                }

                videobuf_vm_open(vma);
                return 0;
            }
        }
    }

    return ret;
}

int videobuf_mmap_setup(struct videobuf_queue *q, struct vm_area_struct *vma)
{
	struct videobuf_buffer *b = NULL;
	int ret = -EINVAL;

	/* Check if the requested area is writable and shared */
	if (vma->vm_flags & (VM_WRITE | VM_SHARED)) {
		/* Search for the first suitable buffer in the queue */
		list_for_each_entry(b, &q->bs, q) {
			if (b->type != q->type || b->memory != VIDEOMemory)
				continue;
			if (vma->vm_start != b->offset)
				continue;
			break;
		}
	}

	if (!b)
		return -EINVAL;

	/* Allocate the mapping structure */
	vma->vm_ops = &videobuf_vm_ops;
	vma->vm_private_data = b;

	/* Attempt to remap virtual memory to physical memory */
	ret = remap_pfn_range(vma, vma->vm_start,
			      PFN_DOWN(b->bo->paddr),
			      vma->vm_end - vma->vm_start,
			      vma->vm_page_prot);
	if (ret < 0) {
		/* If remapping fails, store vma for later use */
		b->vma = vma;
	} else {
		b->vma = NULL;
	}

	/* Log the mapping details */
	pr_debug("Mapped buffer %p at 0x%lx (size 0x%lx)\n",
		 b, vma->vm_start, vma->vm_end - vma->vm_start);

	return 0;
}
